626	// GetVersion returns one version's full parameters by ID. The requested
627	// version's stored archive document must still satisfy every registration
628	// rule in full — re-validated from its raw bytes with the same parser
629	// registrations pass — before its parameters are returned: the decoded
630	// struct cannot tell a missing enabled, severity or multiplier from an
631	// explicitly declared one, so a corrupt declaration would otherwise be
632	// shown with silently zeroed or defaulted parameters. An explicit
633	// enabled:false is a legal off state, but a disabled rule still has to
634	// carry complete, in-range parameters; a missing or null rule object or
635	// field, a wrong type, an out-of-range number, an unknown or duplicate
636	// field all fail with ErrCorruptVersion naming the version and the
637	// offending rule or field — never completed from defaults, the enabled
638	// version or the built-in rules. Only the requested version is judged: a
639	// corrupt sibling — even the currently enabled one — does not block
640	// showing an intact version, and an id that no stored declaration carries
641	// stays an ErrUnknownVersion failure (the id string is matched exactly,
642	// never case-folded or trimmed). The built-in version is constructed in
643	// code and always queryable, whether or not the archive directory exists.
644	// A wholly unparseable archive still fails as archive corruption. The
645	// query is read-only: version declarations, the enabled marker and the
646	// archived reports are never modified.
647	func GetVersion(dir, id string) (RuleVersion, error) {
648		if id == BuiltinVersionID {
649			return BuiltinVersion(), nil
650		}
651		if _, serr := os.Stat(dir); errors.Is(serr, os.ErrNotExist) {
652			return RuleVersion{}, fmt.Errorf("%w: %s", ErrUnknownVersion, id)
653		}
654		lock, err := lockArchive(dir, syscall.LOCK_SH)
655		if err != nil {
656			return RuleVersion{}, err
657		}
658		defer lock.Close()
659	
660		// Decode with each registered version kept as its raw stored document,
661		// the same shape a replay or an enable uses: a wrong-typed field in one
662		// version is that version's corruption rather than whole-archive
663		// corruption, and a corrupt sibling cannot block an intact candidate.
664		raw, err := readArchiveBytes(dir)
665		if err != nil {
666			return RuleVersion{}, err
667		}
668		data := replayArchiveDoc{Records: []record{}}
669		if raw != nil {
670			if err := json.Unmarshal(raw, &data); err != nil {
671				return RuleVersion{}, fmt.Errorf("archive is corrupted: %w", err)
672			}
673		}
674		return intactVersion(data.Versions, id)
675	}
