685	// CompareResult is the outcome of re-judging one archived block under a
686	// different rule version. It carries both versions' parameters, both full
687	// conclusion sets, the raw swap evidence, and the per-transaction diff.
688	type CompareResult struct {
689		ChainID          string          `json:"chainId"`
690		BlockHash        string          `json:"blockHash"`
691		BlockNumber      int64           `json:"blockNumber"`
692		OriginalVersion  RuleVersion     `json:"originalVersion"`
693		ComparedVersion  RuleVersion     `json:"comparedVersion"`
694		OriginalFindings []ReportFinding `json:"originalFindings"`
695		ComparedFindings []ReportFinding `json:"comparedFindings"`
696		Swaps            []Swap          `json:"swaps"`
697		Added            []ReportFinding `json:"added"`
698		Removed          []ReportFinding `json:"removed"`
699		Changed          []FindingChange `json:"changed"`
700	}
701	
702	// rawVersionArchiveDoc mirrors the archive file the way a comparison and a
703	// review-range evaluation read it: records and reviews are fully decoded,
704	// but each registered version is kept as its raw stored document. A corrupt
705	// version entry — a wrong-typed field, say — then cannot break the read or
706	// masquerade as whole-archive corruption; it is judged on its own by
707	// intactVersion, so a corrupt sibling never contaminates an intact
708	// candidate or the built-in version.
709	type rawVersionArchiveDoc struct {
710		Records  []record          `json:"records"`
711		Versions []json.RawMessage `json:"versions"`
712		Reviews  []ReviewObject    `json:"reviews"`
713	}
714	
715	// Compare re-runs detection for one archived block under the given
716	// registered version and diffs the conclusions against the archived
717	// report. It only reads the archive: the original input file is not
718	// needed, and neither the archived report nor the enabled version is
719	// modified. The named version's stored document must still satisfy the
720	// registration rules in full; a corrupt one fails with ErrCorruptVersion
721	// rather than comparing under zeroed or substituted parameters.
722	func Compare(dir, chainID, blockHash, versionID string) (CompareResult, error) {
723		if _, err := os.Stat(dir); err != nil {
724			if errors.Is(err, os.ErrNotExist) {
725				return CompareResult{}, ErrUnknownBlock
726			}
727			return CompareResult{}, err
728		}
729		lock, err := lockArchive(dir, syscall.LOCK_SH)
730		if err != nil {
731			return CompareResult{}, err
732		}
733		defer lock.Close()
734	
735		raw, err := readArchiveBytes(dir)
736		if err != nil {
737			return CompareResult{}, err
738		}
739		var doc rawVersionArchiveDoc
740		if len(raw) > 0 {
741			if err := json.Unmarshal(raw, &doc); err != nil {
742				return CompareResult{}, fmt.Errorf("archive is corrupted: %w", err)
743			}
744		}
745		var rec *record
746		for i := range doc.Records {
747			if doc.Records[i].ChainID == chainID && doc.Records[i].BlockHash == blockHash {
748				rec = &doc.Records[i]
749				break
750			}
751		}
752		if rec == nil {
753			return CompareResult{}, ErrUnknownBlock
754		}
755		// The requested version must be intact in the archive: re-validate its
756		// stored document before judging anything, so a corrupt version fails
757		// the same way even when the block has no swaps and detection would
758		// produce no conclusions at all.
759		compared, err := intactVersion(doc.Versions, versionID)
760		if err != nil {
761			return CompareResult{}, err
762		}
763		original := rec.Findings
764		if original == nil {
765			original = []ReportFinding{}
766		}
767		rejudged := DetectBlockWithRules(rec.Swaps, compared.Rules)
768		swaps := rec.Swaps
769		if swaps == nil {
770			swaps = []Swap{}
771		}
772	
773		origByTx := make(map[string]ReportFinding, len(original))
774		for _, f := range original {
775			origByTx[f.TxHash] = f
776		}
777		compByTx := make(map[string]ReportFinding, len(rejudged))
778		for _, f := range rejudged {
779			compByTx[f.TxHash] = f
780		}
781		added := []ReportFinding{}
782		removed := []ReportFinding{}
783		changed := []FindingChange{}
784		for _, f := range rejudged {
785			if o, ok := origByTx[f.TxHash]; ok {
786				// A transaction present on both sides with a different kind or
787				// severity is a change, never an add plus a remove.
788				if o.Kind != f.Kind || o.Severity != f.Severity {
789					changed = append(changed, FindingChange{TxHash: f.TxHash, Original: o, Compared: f})
790				}
791			} else {
792				added = append(added, f)
793			}
794		}
795		for _, f := range original {
796			if _, ok := compByTx[f.TxHash]; !ok {
797				removed = append(removed, f)
798			}
799		}
800		byTx := func(fs []ReportFinding) {
801			sort.Slice(fs, func(i, j int) bool { return fs[i].TxHash < fs[j].TxHash })
802		}
803		byTx(added)
804		byTx(removed)
805		sort.Slice(changed, func(i, j int) bool { return changed[i].TxHash < changed[j].TxHash })
806	
807		return CompareResult{
808			ChainID:          rec.ChainID,
809			BlockHash:        rec.BlockHash,
810			BlockNumber:      rec.BlockNumber,
811			OriginalVersion:  rec.ruleVersion(),
812			ComparedVersion:  compared,
813			OriginalFindings: original,
814			ComparedFindings: rejudged,
815			Swaps:            swaps,
816			Added:            added,
817			Removed:          removed,
818			Changed:          changed,
819		}, nil
820	}
821

