1	package mevwatch
2	
3	// Regression coverage for `report` (Query) against an archived report
4	// whose saved rule-version declaration has decayed since the report was
5	// written. Querying a report must first prove the complete version
6	// declaration the report archived — a non-empty id, sandwich and
7	// displacement each with a boolean enabled and an integer severity 1-5,
8	// and a displacement multiplier 2-100 — still satisfies every
9	// registration rule, using the same raw-document proof registration,
10	// enabling, comparison, evaluation and replay already demand. Until that
11	// proof succeeds no report is returned: a missing or null parameter must
12	// never be shown as a zero value, a null or missing id must never be
13	// explained as the built-in rules, and parameters must never be completed
14	// from the registered or currently enabled version. Only an old-format
15	// record with no version key at all keeps the built-in interpretation.
16	// The query is read-only: success or failure leaves the archive exactly
17	// as it was, and a block that was never archived stays ErrUnknownBlock.
18	
19	import (
20		"encoding/json"
21		"errors"
22		"os"
23		"path/filepath"
24		"reflect"
25		"strings"
26		"testing"
27	)
28	
29	// rewriteStoredReportVersion rewrites the version declaration embedded in
30	// one archived record (not the same-id entry in the versions registry)
31	// through mutate.
32	func rewriteStoredReportVersion(t *testing.T, dir, chain, hash string, mutate func(ver map[string]any)) {
33		t.Helper()
34		path := filepath.Join(dir, archiveFileName)
35		raw, err := os.ReadFile(path)
36		if err != nil {
37			t.Fatal(err)
38		}
39		var doc map[string]any
40		if err := json.Unmarshal(raw, &doc); err != nil {
41			t.Fatal(err)
42		}
43		records, ok := doc["records"].([]any)
44		if !ok {
45			t.Fatalf("no records array in archive: %s", raw)
46		}
47		found := false
48		for _, r := range records {
49			rec, ok := r.(map[string]any)
50			if !ok || rec["chainId"] != chain || rec["blockHash"] != hash {
51				continue
52			}
53			ver, ok := rec["version"].(map[string]any)
54			if !ok {
55				t.Fatalf("record %s/%s has no object version to rewrite: %v", chain, hash, rec["version"])
56			}
57			mutate(ver)
58			found = true
59		}
60		if !found {
61			t.Fatalf("record %s/%s not found in archive", chain, hash)
62		}
63		out, err := json.MarshalIndent(doc, "", "  ")
64		if err != nil {
65			t.Fatal(err)
66		}
67		if err := os.WriteFile(path, out, 0o644); err != nil {
68			t.Fatal(err)
69		}
70	}
71	
72	// replaceStoredReportVersion replaces the embedded version declaration of
73	// one record wholesale — used for null, an empty object, a reserved-id
74	// declaration and versions the registry does not carry.
75	func replaceStoredReportVersion(t *testing.T, dir, chain, hash string, value any) {
76		t.Helper()
77		path := filepath.Join(dir, archiveFileName)
78		raw, err := os.ReadFile(path)
79		if err != nil {
80			t.Fatal(err)
81		}
82		var doc map[string]any
83		if err := json.Unmarshal(raw, &doc); err != nil {
84			t.Fatal(err)
85		}
86		for _, r := range doc["records"].([]any) {
87			rec := r.(map[string]any)
88			if rec["chainId"] == chain && rec["blockHash"] == hash {
89				rec["version"] = value
90				out, err := json.MarshalIndent(doc, "", "  ")
91				if err != nil {
92					t.Fatal(err)
93				}
94				if err := os.WriteFile(path, out, 0o644); err != nil {
95					t.Fatal(err)
96				}
97				return
98			}
99		}
100		t.Fatalf("record %s/%s not found in archive", chain, hash)
101	}
102	
103	// assertQueryRefused runs one failing Query and pins the shape the report
104	// command relies on: ErrCorruptVersion wrapping the cause, never an
105	// unknown-block or unknown-version misread, naming the target chain and
106	// block plus every required extra substring, and leaving the archive
107	// byte-identical.
108	func assertQueryRefused(t *testing.T, dir, chain, hash string, want ...string) {
109		t.Helper()
110		before := readArchiveFile(t, dir)
111		report, err := Query(dir, chain, hash)
112		if err == nil {
113			t.Fatalf("corrupt report returned successfully: %+v", report)
114		}
115		if !errors.Is(err, ErrCorruptVersion) {
116			t.Fatalf("error = %v, want ErrCorruptVersion", err)
117		}
118		if errors.Is(err, ErrUnknownBlock) || errors.Is(err, ErrUnknownVersion) {
119			t.Fatalf("corrupt report misreported as unknown block/version: %v", err)
120		}
121		msg := err.Error()
122		for _, sub := range append([]string{chain, hash}, want...) {
123			if !strings.Contains(msg, sub) {
124				t.Fatalf("error %q must name %q", msg, sub)
125			}
126		}
127		if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
128			t.Fatalf("failed report query changed the archive")
129		}
130		// The failure is not a write-side repair: querying again fails the same
131		// way, and no report JSON is ever produced.
132		if _, err := Query(dir, chain, hash); !errors.Is(err, ErrCorruptVersion) {
133			t.Fatalf("second query did not fail the same way: %v", err)
134		}
135	}
136	
137	// TestQueryCorruptSavedVersionRefused runs the full corruption matrix
138	// against the declaration embedded in the archived report (the registered
139	// versions section is left intact): every way the saved document can stop
140	// satisfying the registration rules must fail Query with
141	// ErrCorruptVersion, naming chain, block, the saved id and the offending
142	// rule or field.
143	func TestQueryCorruptSavedVersionRefused(t *testing.T) {
144		for _, tc := range corruptVersionCases {
145			t.Run(tc.name, func(t *testing.T) {
146				dir := setupCorruptCompareArchive(t)
147				rewriteStoredReportVersion(t, dir, "1", "0xblk", func(ver map[string]any) {
148					tc.mutate(t, ver)
149				})
150	
151				assertQueryRefused(t, dir, "1", "0xblk", "candC", tc.wantErr)
152	
153				// The report's damage lives in its own saved declaration; the
154				// refusal is read-only, so no missing parameter is completed or
155				// fixed (assertQueryRefused compares the archive bytes and
156				// re-queries). Registry independence for structural damage is
157				// covered separately in TestQueryUsesSavedParametersNotRegistry;
158				// a JSON type mismatch in the embedded copy is intentionally not
159				// read back through the registry, whose whole-archive typed
160				// decode predates and is outside this fix.
161			})
162		}
163	}
164	
165	// TestQueryNullAndEmptySavedVersionCorrupt pins the exact misread being
166	// fixed: version:null used to decode into the built-in explanation, and
167	// {} or an incomplete object decoded into silently zeroed parameters. All
168	// three must fail as corruption; only a wholly missing version key is the
169	// legacy built-in shape.
170	func TestQueryNullAndEmptySavedVersionCorrupt(t *testing.T) {
171		cases := []struct {
172			name  string
173			value any
174		}{
175			{"null", nil},
176			{"empty object", map[string]any{}},
177			{"incomplete object", map[string]any{"id": "candC"}},
178			{"non-object number", 5},
179			{"non-object string", "builtin"},
180			{"array", []any{}},
181		}
182		for _, tc := range cases {
183			t.Run(tc.name, func(t *testing.T) {
184				dir := setupCorruptCompareArchive(t)
185				replaceStoredReportVersion(t, dir, "1", "0xblk", tc.value)
186				// The id may be unreadable for null/{}/scalars; the message must
187				// still name the chain and block and never call this an unknown
188				// block/version.
189				assertQueryRefused(t, dir, "1", "0xblk")
190			})
191		}
192	}
193	
194	// TestQueryBuiltinIDDoesNotBypassValidation proves an id of "builtin"
195	// names the same saved declaration as any other id and is validated in
196	// full: a complete built-in declaration is shown, a damaged one is
197	// refused as corruption (never auto-replaced by the in-code builtin).
198	func TestQueryBuiltinIDDoesNotBypassValidation(t *testing.T) {
199		dir := setupCorruptCompareArchive(t)
200	
201		// A complete declaration carrying the reserved id stands on its own.
202		builtinFull := map[string]any{
203			"id": "builtin",
204			"rules": map[string]any{
205				"sandwich":     map[string]any{"enabled": true, "severity": 3},
206				"displacement": map[string]any{"enabled": true, "severity": 2, "multiplier": 2},
207			},
208		}
209		replaceStoredReportVersion(t, dir, "1", "0xblk", builtinFull)
210		r, err := Query(dir, "1", "0xblk")
211		if err != nil {
212			t.Fatalf("a complete builtin-id declaration must be shown: %v", err)
213		}
214		if r.Version != BuiltinVersion() {
215			t.Fatalf("version = %+v, want builtin parameters", r.Version)
216		}
217	
218		// The same id with a missing field is corrupt, and the failure points
219		// at "builtin" rather than silently substituting it.
220		builtinDamaged := map[string]any{
221			"id": "builtin",
222			"rules": map[string]any{
223				"sandwich":     map[string]any{"enabled": true, "severity": 3},
224				"displacement": map[string]any{"enabled": true, "severity": 2},
225			},
226		}
227		replaceStoredReportVersion(t, dir, "1", "0xblk", builtinDamaged)
228		assertQueryRefused(t, dir, "1", "0xblk", BuiltinVersionID, "multiplier")
229	}
230	
231	// TestQueryDuplicateFieldsInSavedVersionRefused covers decay registration
232	// could never have produced: a repeated field in the saved declaration,
233	// including an escaped spelling and a case-only spelling that name the
234	// same field. The raw bytes are patched directly because a JSON map
235	// cannot hold two keys; the report record precedes the versions array.
236	func TestQueryDuplicateFieldsInSavedVersionRefused(t *testing.T) {
237		cases := []struct{ name, field string }{
238			{"exact", `"severity": 4, `},
239			{"case variant", `"Severity": 4, `},
240			// "v" written via its JSON escape (v) decodes to the same key.
241			{"escaped", "\"se\\u0076erity\": 4, "},
242		}
243		for _, dup := range cases {
244			t.Run(dup.name, func(t *testing.T) {
245				dir := setupCorruptCompareArchive(t)
246				path := filepath.Join(dir, archiveFileName)
247				text := string(readArchiveFile(t, dir))
248				// The first candC declaration in the file is the one embedded in
249				// the record (records precede the versions registry).
250				versionsAt := strings.Index(text, `"versions":`)
251				if versionsAt < 0 {
252					t.Fatal("versions section not found")
253				}
254				at := strings.Index(text[:versionsAt], `"id": "candC"`)
255				if at < 0 {
256					t.Fatal("record's embedded candC declaration not found")
257				}
258				anchor := `"severity": 4,`
259				field := strings.Index(text[at:versionsAt], anchor)
260				if field < 0 {
261					t.Fatal("severity field not found in embedded declaration")
262				}
263				pos := at + field
264				patched := text[:pos] + dup.field + text[pos:]
265				if err := os.WriteFile(path, []byte(patched), 0o644); err != nil {
266					t.Fatal(err)
267				}
268				report, err := Query(dir, "1", "0xblk")
269				if err == nil {
270					t.Fatalf("duplicate-field declaration shown: %+v", report)
271				}
272				if !errors.Is(err, ErrCorruptVersion) || !errors.Is(err, ErrDuplicateField) {
273					t.Fatalf("err = %v, want ErrCorruptVersion wrapping ErrDuplicateField", err)
274				}
275				if !strings.Contains(err.Error(), "candC") || !strings.Contains(err.Error(), "severity") {
276					t.Fatalf("error must name candC and severity, got %v", err)
277				}
278				if after := readArchiveFile(t, dir); after == nil || !strings.Contains(string(after), dup.field) {
279					t.Fatalf("failed query repaired the duplicate field")
280				}
281			})
282		}
283	}
284	
285	// TestQueryExplicitlyDisabledRulesAccepted proves enabled:false is a legal
286	// saved off state, not a missing field: a report archived with both rules
287	// off but complete parameters is returned normally, while a disabled rule
288	// that lost a parameter is still corrupt.
289	func TestQueryExplicitlyDisabledRulesAccepted(t *testing.T) {
290		dir := setupCorruptCompareArchive(t)
291		off := map[string]any{
292			"id": "off",
293			"rules": map[string]any{
294				"sandwich":     map[string]any{"enabled": false, "severity": 1},
295				"displacement": map[string]any{"enabled": false, "severity": 1, "multiplier": 2},
296			},
297		}
298		replaceStoredReportVersion(t, dir, "1", "0xblk", off)
299		r, err := Query(dir, "1", "0xblk")
300		if err != nil {
301			t.Fatalf("an explicitly disabled, complete declaration must be accepted: %v", err)
302		}
303		if r.Version.ID != "off" || r.Version.Rules.Sandwich.Enabled || r.Version.Rules.Displacement.Enabled {
304			t.Fatalf("saved off state not returned: %+v", r.Version)
305		}
306	
307		// Disabled does not pardon a missing severity: the rule still has to be
308		// declared completely.
309		offBroken := map[string]any{
310			"id": "off",
311			"rules": map[string]any{
312				"sandwich":     map[string]any{"enabled": false},
313				"displacement": map[string]any{"enabled": false, "severity": 1, "multiplier": 2},
314			},
315		}
316		replaceStoredReportVersion(t, dir, "1", "0xblk", offBroken)
317		assertQueryRefused(t, dir, "1", "0xblk", "off", "severity")
318	}
319	
320	// TestQueryUsesSavedParametersNotRegistry proves the report is explained
321	// by the declaration it archived: enabling another version, damaging the
322	// same-id registry entry, or pointing at an id the registry never carried
323	// neither changes nor blocks an intact saved report, and no parameters are
324	// pulled back out of the registry.
325	func TestQueryUsesSavedParametersNotRegistry(t *testing.T) {
326		dir := setupCompareArchive(t) // records archived under archA, liveB enabled
327	
328		r, err := Query(dir, "1", "0xblk")
329		if err != nil {
330			t.Fatal(err)
331		}
332		if want := mustRuleVersion(t, archivedVersionSpec); r.Version != want {
333			t.Fatalf("report must show its saved archA parameters regardless of the enabled version: %+v", r.Version)
334		}
335	
336		// Damage the registered archA entry; the report's own intact embedded
337		// declaration is unaffected and still returned byte for byte, with no
338		// parameters pulled from the registry.
339		rewriteStoredVersion(t, dir, "archA", func(ver map[string]any) {
340			delete(storedRule(t, ver, "displacement"), "multiplier")
341		})
342		r2, err := Query(dir, "1", "0xblk")
343		if err != nil {
344			t.Fatalf("a corrupt registry sibling must not block an intact saved report: %v", err)
345		}
346		if want := mustRuleVersion(t, archivedVersionSpec); r2.Version != want {
347			t.Fatalf("report borrowed registry parameters: %+v, want %+v", r2.Version, want)
348		}
349	
350		// Conversely, an intact registry does not rescue a corrupt report:
351		// damage only the report's own copy while the same-id registry entry
352		// stays intact.
353		dir2 := setupCompareArchive(t)
354		rewriteStoredReportVersion(t, dir2, "1", "0xblk", func(ver map[string]any) {
355			storedRule(t, ver, "displacement")["multiplier"] = 0
356		})
357		assertQueryRefused(t, dir2, "1", "0xblk", "archA", "multiplier")
358	}
359	
360	// TestQueryUnknownVersionIDInReportStillValid proves the saved declaration
361	// is self-contained: even an id the archive's registry never registered is
362	// a valid explanation as long as the document itself is complete.
363	func TestQueryUnknownVersionIDInReportStillValid(t *testing.T) {
364		dir := setupCorruptCompareArchive(t)
365		stray := map[string]any{
366			"id": "never-registered",
367			"rules": map[string]any{
368				"sandwich":     map[string]any{"enabled": true, "severity": 5},
369				"displacement": map[string]any{"enabled": true, "severity": 5, "multiplier": 9},
370			},
371		}
372		replaceStoredReportVersion(t, dir, "1", "0xblk", stray)
373		r, err := Query(dir, "1", "0xblk")
374		if err != nil {
375			t.Fatalf("a complete self-contained declaration must not need registry backing: %v", err)
376		}
377		if r.Version.ID != "never-registered" || r.Version.Rules.Displacement.Multiplier != 9 {
378			t.Fatalf("saved parameters not returned: %+v", r.Version)
379		}
380		if _, err := GetVersion(dir, "never-registered"); !errors.Is(err, ErrUnknownVersion) {
381			t.Fatalf("the report-only id must not have been inserted into the registry: %v", err)
382		}
383	}
384	
385	// TestQueryLegacyArchiveWithoutVersionUsesBuiltin proves the one legacy
386	// carve-out: a record with no version key at all is still explained by the
387	// built-in rules, with identity, height, swap count, conclusions and
388	// evidence unchanged.
389	func TestQueryLegacyArchiveWithoutVersionUsesBuiltin(t *testing.T) {
390		dir := t.TempDir()
391		legacy := `{"records":[{"chainId":"1","blockHash":"0old","blockNumber":5,` +
392			`"swaps":[{"TxHash":"0f","Pool":"p1","Trader":"bot","In":7,"Out":6,"GasPrice":90,"Index":0},` +
393			`{"TxHash":"0v","Pool":"p1","Trader":"user","In":5,"Out":4,"GasPrice":10,"Index":1},` +
394			`{"TxHash":"0b","Pool":"p1","Trader":"bot","In":3,"Out":5,"GasPrice":80,"Index":2}],` +
395			`"findings":[{"kind":"sandwich","severity":3,"txHash":"0v","evidence":[` +
396			`{"TxHash":"0f","Pool":"p1","Trader":"bot","In":7,"Out":6,"GasPrice":90,"Index":0},` +
397			`{"TxHash":"0v","Pool":"p1","Trader":"user","In":5,"Out":4,"GasPrice":10,"Index":1},` +
398			`{"TxHash":"0b","Pool":"p1","Trader":"bot","In":3,"Out":5,"GasPrice":80,"Index":2}]}]}]}`
399		if err := os.WriteFile(filepath.Join(dir, archiveFileName), []byte(legacy), 0o644); err != nil {
400			t.Fatal(err)
401		}
402		before := readArchiveFile(t, dir)
403		r, err := Query(dir, "1", "0old")
404		if err != nil {
405			t.Fatalf("legacy report must query under builtin: %v", err)
406		}
407		if r.Version != BuiltinVersion() {
408			t.Fatalf("version = %+v, want builtin", r.Version)
409		}
410		if r.ChainID != "1" || r.BlockHash != "0old" || r.BlockNumber != 5 || r.SwapCount != 3 {
411			t.Fatalf("identity/height/swap count damaged: %+v", r)
412		}
413		if len(r.Findings) != 1 || r.Findings[0].Kind != "sandwich" || r.Findings[0].Severity != 3 ||
414			len(r.Findings[0].Evidence) != 3 {
415			t.Fatalf("legacy findings/evidence damaged: %+v", r.Findings)
416		}
417		if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
418			t.Fatalf("legacy query rewrote the archive")
419		}
420	}
421	
422	// TestQueryUnknownBlockUnchanged proves block existence still governs the
423	// query: a never-archived block returns ErrUnknownBlock even when a
424	// different record in the same archive is corrupt, and the missing-dir
425	// case stays ErrUnknownBlock.
426	func TestQueryUnknownBlockUnchanged(t *testing.T) {
427		dir := setupCorruptCompareArchive(t)
428		rewriteStoredReportVersion(t, dir, "1", "0xblk", func(ver map[string]any) {
429			delete(storedRule(t, ver, "displacement"), "multiplier")
430		})
431		// The corrupt record fails as corruption...
432		if _, err := Query(dir, "1", "0xblk"); !errors.Is(err, ErrCorruptVersion) {
433			t.Fatalf("corrupt record error = %v, want ErrCorruptVersion", err)
434		}
435		// ...but an absent block is still an unknown-block failure, not a
436		// spillover corruption error.
437		for _, id := range [][2]string{{"1", "0xother"}, {"9", "0xblk"}} {
438			if _, err := Query(dir, id[0], id[1]); !errors.Is(err, ErrUnknownBlock) {
439				t.Fatalf("Query(%s,%s) = %v, want ErrUnknownBlock", id[0], id[1], err)
440			}
441		}
442		if _, err := Query(filepath.Join(dir, "missing"), "1", "0xblk"); !errors.Is(err, ErrUnknownBlock) {
443			t.Fatalf("missing directory must stay ErrUnknownBlock")
444		}
445	}
446	
447	// TestQuerySuccessContentUnchanged proves a healthy report still carries
448	// exactly the original block identity, height, swap count, the original
449	// conclusions in their stored order with all swap evidence, and the saved
450	// parameters — with no re-detection.
451	func TestQuerySuccessContentUnchanged(t *testing.T) {
452		dir := setupCompareArchive(t)
453		r, err := Query(dir, "1", "0xblk")
454		if err != nil {
455			t.Fatal(err)
456		}
457		if r.ChainID != "1" || r.BlockHash != "0xblk" || r.BlockNumber != 100 || r.SwapCount != 13 {
458			t.Fatalf("identity/height/swap count wrong: %+v", r)
459		}
460		if want := mustRuleVersion(t, archivedVersionSpec); r.Version != want {
461			t.Fatalf("version = %+v, want archA", r.Version)
462		}
463		wantFindings := []struct {
464			tx       string
465			kind     string
466			severity int
467			evidence int
468		}{
469			{"0xa0v", "sandwich", 4, 3},
470			{"0xe0v", "sandwich", 4, 3},
471			{"0xb0v", "displacement", 1, 2},
472		}
473		if len(r.Findings) != len(wantFindings) {
474			t.Fatalf("findings = %+v", r.Findings)
475		}
476		for i, w := range wantFindings {
477			got := r.Findings[i]
478			if got.TxHash != w.tx || got.Kind != w.kind || got.Severity != w.severity ||
479				len(got.Evidence) != w.evidence {
480				t.Fatalf("findings[%d] = %+v, want %+v", i, got, w)
481			}
482		}
483		if r.Findings[0].Evidence[0] != (Swap{TxHash: "0xa0f", Pool: "p1", Trader: "bot", In: 1, Out: 1, GasPrice: 90, Index: 0}) {
484			t.Fatalf("raw swap evidence damaged: %+v", r.Findings[0].Evidence[0])
485		}
486		// Deterministic across reads.
487		again, err := Query(dir, "1", "0xblk")
488		if err != nil {
489			t.Fatal(err)
490		}
491		if !reflect.DeepEqual(r, again) {
492			t.Fatalf("repeated query differs:\n%+v\n%+v", r, again)
493		}
494	}
