package mevwatch

import (
	"errors"
	"strings"
	"testing"
)

func TestTmpReplayCorruptSavedVersion(t *testing.T) {
	newBlock := cmpBlockLine("1", "0xnew", 8,
		cmpSwap("0xn1", "p1", "w", 40, 0),
		cmpSwap("0xn2", "p1", "u", 10, 1),
	)
	archivedLine := cmpBlockLine("1", "0xblk", 7,
		cmpSwap("0xf", "p1", "w", 40, 0),
		cmpSwap("0xv", "p1", "u", 10, 1),
	)

	// 1. Corrupt embedded declaration (multiplier removed), old block last.
	dir := setupCorruptCompareArchive(t)
	rewriteStoredReportVersion(t, dir, "1", "0xblk", func(ver map[string]any) {
		delete(storedRule(t, ver, "displacement"), "multiplier")
	})
	before := readArchiveFile(t, dir)
	reports, err := Replay(strings.NewReader(newBlock+"\n"+archivedLine), dir)
	if !errors.Is(err, ErrCorruptVersion) {
		t.Fatalf("err = %v, want ErrCorruptVersion", err)
	}
	if reports != nil {
		t.Fatalf("reports leaked: %+v", reports)
	}
	msg := err.Error()
	for _, want := range []string{"line 2", "1", "0xblk", "candC", "multiplier"} {
		if !strings.Contains(msg, want) {
			t.Fatalf("error %q must name %q", msg, want)
		}
	}
	if errors.Is(err, ErrUnknownBlock) || errors.Is(err, ErrUnknownVersion) {
		t.Fatalf("misreported as unknown: %v", err)
	}
	if after := readArchiveFile(t, dir); string(before) != string(after) {
		t.Fatalf("archive changed")
	}
	if _, err := Query(dir, "1", "0xnew"); !errors.Is(err, ErrUnknownBlock) {
		t.Fatalf("new block archived by refused replay")
	}

	// 2. version:null must not be read as builtin.
	dir2 := setupCorruptCompareArchive(t)
	replaceStoredReportVersion(t, dir2, "1", "0xblk", nil)
	if _, err := Replay(strings.NewReader(archivedLine), dir2); !errors.Is(err, ErrCorruptVersion) {
		t.Fatalf("null version err = %v, want ErrCorruptVersion", err)
	}

	// 3. Corrupt old block first, new block second: same refusal.
	dir3 := setupCorruptCompareArchive(t)
	rewriteStoredReportVersion(t, dir3, "1", "0xblk", func(ver map[string]any) {
		delete(storedRule(t, ver, "displacement"), "multiplier")
